widget.solution:
def value(f, x, p):
    return sum(c * x ** k for k, c in enumerate(f)) % p


def roots_mod(f, p):
    """Sorted roots of f in Z_p (f lowest degree first)."""
    return [x for x in range(p) if value(f, x, p) == 0]


def irreducible_small(f, p):
    """For degree 2 or 3 over Z_p: True when f has no root."""
    g = [c % p for c in f]
    while len(g) > 1 and g[-1] == 0:
        g.pop()
    if len(g) - 1 not in (2, 3):
        raise ValueError("the root test decides degrees 2 and 3 only")
    return not roots_mod(g, p)
